export const VIDEO_GOAL_TOPIC_STORY_CATALOG=source;
export const VIDEO_STORY_CATEGORY_IDS=Object.freeze(source.categoryOrder.slice());
const categoriesById=new Map(source.categories.map(c=>[c.id,c]));
const topicsById=new Map(source.categories.flatMap(c=>c.topics.map(t=>[t.id,{...t,categoryId:c.id}])));
const storiesById=new Map([...topicsById.values()].flatMap(t=>t.scenarios.map(s=>[s.id,{...s,topicId:t.id,categoryId:t.categoryId,legacyTheme:t.legacyTheme}])));
export const VIDEO_STORY_COUNTS=Object.freeze({categories:categoriesById.size,topics:topicsById.size,scenarios:storiesById.size});
export function videoStoryCategory(id){return categoriesById.get(id)||null;}
export function videoStoryTopic(id){return topicsById.get(id)||null;}
export function videoStoryScenario(id){return storiesById.get(id)||null;}
export function videoStoryTopics(categoryId){return (categoriesById.get(categoryId)?.topics||[]).slice();}
export function videoStoryScenarios(topicId){return (topicsById.get(topicId)?.scenarios||[]).slice();}
export function videoStoryLegacyGoalTopic(goalId){return topicsById.get(source.legacyGoalTopicIds[goalId])||null;}
export function videoStoryPlan(scenarioId){
 const s=storiesById.get(scenarioId);
 if(!s)return null;
 return {status:"media_unassigned",canRender:false,scenarioId:s.id,topicId:s.topicId,categoryId:s.categoryId,legacyTheme:s.legacyTheme,shots:s.shots.map(shot=>({...shot,clipId:null,photoId:null}))};
}
export function findVideoStoryTopics({categoryId,query="",locale="ru"}={}){
 const cat=categoriesById.get(categoryId);
 if(!cat)return [];
 const lang=["ru","en","es"].includes(locale)?locale:"ru";
 const text=typeof query==="string"?query.trim().toLocaleLowerCase().slice(0,160):"";
 const words=text.split(/\s+/u).filter(word=>word.length>=3);
 return cat.topics.map((topic,index)=>{
  const tokens=[topic.label[lang],...topic.keywords].map(x=>x.toLocaleLowerCase());
  return {id:topic.id,label:topic.label[lang],index,score:words.reduce((sum,w)=>sum+(tokens.some(x=>x.includes(w))?1:0),0)};
 }).filter(x=>!text||x.score>0).sort((a,b)=>b.score-a.score||a.index-b.index);
}
